#include <iostream>
#include <stack>
using namespace std;

int main() {
    stack<int> s;

    // Push elements
    s.push(10);
    s.push(20);
    s.push(30);

    cout << "Top: " << s.top() << endl;  // 30
    cout << "Size: " << s.size() << endl; // 3

    s.pop();  // 30 removed
    cout << "Top after pop: " << s.top() << endl;  // 20

    // Print all elements
    while(!s.empty()) {
        cout << s.top() << " ";
        s.pop();
    }
    // Output: 20 10
    return 0;
}

