#include <stdio.h>
#define MAX 100

int stack[MAX];
int top = -1;

void push(int val) {
    if (top >= MAX - 1) { printf("Overflow\n"); return; }
    stack[++top] = val;
}

int pop() {
    if (top < 0) { printf("Underflow\n"); return -1; }
    return stack[top--];
}

int peek() { return stack[top]; }
int isEmpty() { return top < 0; }

int main() {
    push(10); push(20); push(30);
    printf("Top: %d\n", peek());  // 30
    pop();
    printf("Top after pop: %d\n", peek());  // 20
    return 0;
}

