#include <iostream>
#include <stack>
#include <string>
using namespace std;

// Balanced Parentheses Check
bool isBalanced(string s) {
    stack<char> st;

    for(char c : s) {
        if(c == '(' || c == '{' || c == '[') {
            st.push(c);
        } else {
            if(st.empty()) return false;
            char top = st.top();
            if((c == ')' && top == '(') ||
               (c == '}' && top == '{') ||
               (c == ']' && top == '[')) {
                st.pop();
            } else {
                return false;
            }
        }
    }
    return st.empty();
}

int main() {
    cout << isBalanced("{[()]}") << endl;  // 1 (true)
    cout << isBalanced("{[(])}") << endl;  // 0 (false)
    cout << isBalanced("((()))") << endl;  // 1 (true)
    return 0;
}

